INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9001, 'បើ \(P(A)\) ជាប្រូបាបនៃព្រឹត្តិការណ៍ \(A\) ណាមួយ នោះតម្លៃនៃ \(P(A)\) ត្រូវតែស្ថិតក្នុងចន្លោះណា?', NULL, '["\\(0 \\le P(A) \\le 1\\)", "\\(P(A) \\ge 1\\)", "\\(P(A) < 0\\)", "\\(-1 \\le P(A) \\le 1\\)"]', 0, NULL, 1, 'mcq', 'ប្រូបាបនៃព្រឹត្តិការណ៍ណាមួយតែងតែនៅចន្លោះ ០ និង ១ ជានិច្ច ៖ \(0 \le P(A) \le 1\)។', 'ប្រូបាប', 'easy', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9002, 'គេបោះកាក់មួយដែលមានម្ខាងជារូប (\(H\)) និងម្ខាងទៀតជាលេខ (\(T\)) ចំនួន ១ ដង។ ប្រូបាបដែលបោះបានខាងរូបគឺ ៖', NULL, '["\\(0\\)", "\\(\\dfrac{1}{4}\\)", "\\(1\\)", "\\(\\dfrac{1}{2}\\)"]', 3, NULL, 1, 'mcq', 'ករណីអាច \(\{H, T\}\) មាន ២ ករណីស្រប \(\{H\}\) មាន ១ នាំឱ្យ \(P = \dfrac{1}{2}\) (ឬ \(50\%\))។', 'ប្រូបាប', 'easy', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9003, 'គេបោះគ្រាប់ឡុកឡាក់មួយគ្រាប់ (មានលេខពី ១ ដល់ ៦)។ ចំនួនករណីអាចទាំងអស់ (ទំហំលំហសំណាក) ស្មើ ៖', NULL, '["\\(4\\)", "\\(6\\)", "\\(12\\)", "\\(36\\)"]', 1, NULL, 1, 'mcq', 'លំហសំណាក \(S = \{1, 2, 3, 4, 5, 6\}\) មានចំនួនករណីអាចស្មើ ៦។', 'ប្រូបាប', 'easy', 1, '8', 'ប្រូបាប', NULL, 0);
