INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9004, 'ក្នុងការបង្វិលថាសមួយដែលមាន ៤ ផ្នែកស្មើគ្នា លាបពណ៌បៃតង ស ខ្មៅ និងក្រហម។ ប្រូបាបដែលចុងព្រួញឈប់ចំពណ៌បៃតងគឺ ៖', 'g8-9ed5cbcf2e.svg', '["\\(\\dfrac{3}{4}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{1}{4}\\)", "\\(1\\)"]', 2, NULL, 1, 'mcq', 'ចំនួនករណីអាចស្មើ ៤ ករណីស្របចំពណ៌បៃតងមាន ១ នាំឱ្យ \(P = \dfrac{1}{4} = 25\%\)។', 'ប្រូបាប', 'easy', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9005, 'គេចាប់សន្លឹកប័ណ្ណមួយពីសន្លឹកប័ណ្ណ ១០ សន្លឹកដែលចុះលេខពី ១ ដល់ ១០។ ប្រូបាបដែលចាប់បានសន្លឹកប័ណ្ណលេខសេសគឺ ៖', NULL, '["\\(\\dfrac{2}{5}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{3}{10}\\)", "\\(\\dfrac{1}{10}\\)"]', 1, NULL, 1, 'mcq', 'លេខសេសមាន ៥ គឺ \(\{1, 3, 5, 7, 9\}\) នាំឱ្យ \(P = \dfrac{5}{10} = \dfrac{1}{2} = 50\%\)។', 'ប្រូបាប', 'easy', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9006, 'ក្នុងថង់មួយមានឃ្លីពណ៌ខៀវ ៤ គ្រាប់។ បើគេចាប់យកឃ្លី ១ គ្រាប់ ប្រូបាបដែលចាប់បានឃ្លីពណ៌ក្រហមគឺ ៖', NULL, '["\\(0.5\\)", "\\(1\\)", "\\(\\dfrac{1}{4}\\)", "\\(0\\)"]', 3, NULL, 1, 'mcq', 'ក្នុងថង់គ្មានឃ្លីពណ៌ក្រហមទេ ដូច្នេះករណីស្របស្មើ ០ នាំឱ្យ \(P = 0\) (ព្រឹត្តិការណ៍មិនអាចកើតមាន)។', 'ប្រូបាប', 'easy', 1, '8', 'ប្រូបាប', NULL, 0);
