INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9012, 'គេចាប់សន្លឹកប័ណ្ណមួយពីសន្លឹកប័ណ្ណ ១០ សន្លឹក (លេខ ១ ដល់ ១០)។ ប្រូបាបដែលចាប់បានលេខជាពហុគុណនៃ ៣ គឺ ៖', NULL, '["\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{3}{10}\\)", "\\(\\dfrac{2}{5}\\)", "\\(\\dfrac{1}{10}\\)"]', 1, NULL, 2, 'mcq', 'ពហុគុណនៃ ៣ មាន \(\{3, 6, 9\}\) សរុប ៣ សន្លឹក នាំឱ្យ \(P = \dfrac{3}{10} = 30\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9013, 'ក្នុងប្រអប់មានស្ករសូកូឡា ២៤ គ្រាប់ ក្នុងនោះ ១០ គ្រាប់មានស្នូលក្រែម ៦ គ្រាប់គ្មានស្នូល និងនៅសល់មានស្នូលសណ្តែក។ ប្រូបាបចាប់បានស្ករមានស្នូលសណ្តែកគឺ ៖', NULL, '["\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{5}{12}\\)", "\\(\\dfrac{7}{12}\\)", "\\(\\dfrac{1}{4}\\)"]', 0, NULL, 2, 'mcq', 'ស្ករស្នូលសណ្តែក \(24 - (10 + 6) = 8\) គ្រាប់ នាំឱ្យ \(P = \dfrac{8}{24} = \dfrac{1}{3} \approx 33.33\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9014, 'រដ្ឋាមានស្រោមជើងពណ៌ផ្ទៃមេឃ ៨ ពណ៌ខៀវ ៧ ពណ៌សូកូឡា ១៣ និងពណ៌ក្រហម ៦។ ប្រូបាបដែលចាប់បានស្រោមជើងពណ៌ផ្ទៃមេឃគឺ ៖', NULL, '["\\(\\dfrac{7}{34}\\)", "\\(\\dfrac{4}{17}\\)", "\\(\\dfrac{8}{35}\\)", "\\(\\dfrac{1}{4}\\)"]', 1, NULL, 2, 'mcq', 'ចំនួនសរុប \(8 + 7 + 13 + 6 = 34\) ស្រោម នាំឱ្យ \(P = \dfrac{8}{34} = \dfrac{4}{17} \approx 23.53\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9015, 'ក្នុងថ្នាក់មួយមានសិស្សស្រី ១៤ នាក់ និងប្រុស ១០ នាក់។ គេជ្រើសរើសសិស្សម្នាក់ជាប្រធានថ្នាក់ដោយចៃដន្យ។ ប្រូបាបដែលប្រធានថ្នាក់ជាសិស្សស្រីគឺ ៖', NULL, '["\\(\\dfrac{7}{12}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{5}{12}\\)", "\\(\\dfrac{3}{5}\\)"]', 0, NULL, 2, 'mcq', 'សិស្សសរុប \(14 + 10 = 24\) នាំឱ្យ \(P = \dfrac{14}{24} = \dfrac{7}{12} \approx 58.33\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
