INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9019, 'តាមលំហាត់ខាងលើ ប្រូបាបដែលចាប់បានស្ករសូកូឡាមិនមានស្នូលក្រែមគឺ ៖', NULL, '["\\(\\dfrac{5}{12}\\)", "\\(\\dfrac{7}{12}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{2}{3}\\)"]', 1, NULL, 2, 'mcq', 'ស្ករមិនមានស្នូលក្រែម \(24 - 10 = 14\) គ្រាប់ នាំឱ្យ \(P = \dfrac{14}{24} = \dfrac{7}{12} \approx 58.33\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9020, 'តាមលំហាត់ស្រោមជើងខាងលើ ប្រូបាបដែលចាប់បានស្រោមជើងមិនមែនពណ៌សូកូឡាគឺ ៖', NULL, '["\\(\\dfrac{21}{34}\\)", "\\(\\dfrac{13}{34}\\)", "\\(\\dfrac{7}{17}\\)", "\\(\\dfrac{15}{34}\\)"]', 0, NULL, 2, 'mcq', 'មិនមែនសូកូឡា \(34 - 13 = 21\) ស្រោម នាំឱ្យ \(P = \dfrac{21}{34} \approx 61.76\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9021, 'គេបោះកាក់មួយចំនួន ២ ដង។ ប្រូបាបដែលបោះបានខាងរូបទាំង ២ ដង (\(HH\)) គឺ ៖', NULL, '["\\(\\dfrac{1}{4}\\)", "\\(\\dfrac{1}{8}\\)", "\\(\\dfrac{3}{4}\\)", "\\(\\dfrac{1}{2}\\)"]', 0, NULL, 2, 'mcq', 'ករណីស្រប \(\{HH\}\) មាន ១ ក្នុងចំណោម ៤ នាំឱ្យ \(P = \dfrac{1}{4} = 25\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9022, 'គេបោះគ្រាប់ឡុកឡាក់មួយគ្រាប់។ ប្រូបាបដែលបោះបានលេខចែកដាច់នឹង ៥ គឺ ៖', NULL, '["\\(\\dfrac{1}{6}\\)", "\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{5}{6}\\)"]', 0, NULL, 2, 'mcq', 'លេខចែកដាច់នឹង ៥ ក្នុងចំណោម ១ ដល់ ៦ មានតែមួយគត់គឺ \(\{5\}\) នាំឱ្យ \(P = \dfrac{1}{6}\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9023, 'គេបោះកាក់មួយចំនួន ២ ដង។ ប្រូបាបដែលបោះបានខាងរូបមួយ និងខាងលេខមួយគឺ ៖', NULL, '["\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{3}{4}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{1}{4}\\)"]', 2, NULL, 2, 'mcq', 'ករណីស្រប \(\{HT, TH\}\) មាន ២ នាំឱ្យ \(P = \dfrac{2}{4} = \dfrac{1}{2} = 50\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9024, 'គេបោះគ្រាប់ឡុកឡាក់មួយគ្រាប់។ ប្រូបាបដែលបោះបានលេខធំជាង ១ គឺ ៖', NULL, '["\\(\\dfrac{1}{6}\\)", "\\(1\\)", "\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{5}{6}\\)"]', 3, NULL, 2, 'mcq', 'លេខធំជាង ១ មាន ៥ គឺ \(\{2, 3, 4, 5, 6\}\) នាំឱ្យ \(P = \dfrac{5}{6} \approx 83.33\%\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9025, 'កាក់មួយ និងគ្រាប់ឡុកឡាក់មួយបោះព្រមគ្នា។ ប្រូបាបដែលបោះបានកាក់ខាងរូប និងគ្រាប់ឡុកឡាក់លេខ ៦ គឺ ៖', NULL, '["\\(\\dfrac{7}{12}\\)", "\\(\\dfrac{1}{6}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{1}{12}\\)"]', 3, NULL, 3, 'mcq', 'ករណីស្របមានតែ ១ គត់គឺ \((H, 6)\) ក្នុងចំណោម ១២ ករណី នាំឱ្យ \(P = \dfrac{1}{12} \approx 8.33\%\)។', 'ប្រូបាប', 'hard', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9026, 'គេបោះកាក់មួយចំនួន ៣ ដង។ ប្រូបាបដែលបោះបានខាងរូបទាំងបីដង ឬខាងលេខទាំងបីដងគឺ ៖', NULL, '["\\(\\dfrac{1}{4}\\)", "\\(\\dfrac{1}{8}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{3}{8}\\)"]', 0, NULL, 3, 'mcq', 'ករណីអាច \(2^3 = 8\)។ ករណីស្រប \(\{HHH, TTT\}\) មាន ២ នាំឱ្យ \(P = \dfrac{2}{8} = \dfrac{1}{4} = 25\%\)។', 'ប្រូបាប', 'hard', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9027, 'គេបោះគ្រាប់ឡុកឡាក់ ២ គ្រាប់ព្រមគ្នា។ ចំនួនករណីអាចទាំងអស់គឺ ៖', NULL, '["\\(12\\)", "\\(18\\)", "\\(64\\)", "\\(36\\)"]', 3, NULL, 3, 'mcq', 'គ្រាប់ទី១ មាន ៦ គ្រាប់ទី២ មាន ៦ នាំឱ្យ \(N = 6 \times 6 = 36\) ករណី។', 'ប្រូបាប', 'hard', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9028, 'គេបោះគ្រាប់ឡុកឡាក់ ៣ គ្រាប់ព្រមគ្នា។ ប្រូបាបដែលគ្រាប់ឡុកឡាក់ទាំងបីចេញលេខដូចគ្នាគឺ ៖', NULL, '["\\(\\dfrac{1}{216}\\)", "\\(\\dfrac{1}{6}\\)", "\\(\\dfrac{1}{18}\\)", "\\(\\dfrac{1}{36}\\)"]', 3, NULL, 3, 'mcq', 'ករណីអាច \(6^3 = 216\)។ ករណីស្រប \(\{(1,1,1), \dots, (6,6,6)\}\) មាន ៦ នាំឱ្យ \(P = \dfrac{6}{216} = \dfrac{1}{36} \approx 2.78\%\)។', 'ប្រូបាប', 'hard', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9029, 'គេបោះកាក់មួយចំនួន ៣ ដង។ ប្រូបាបដែលបោះបានខាងរូបពីរ និងខាងលេខមួយគឺ ៖', NULL, '["\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{1}{8}\\)", "\\(\\dfrac{3}{8}\\)", "\\(\\dfrac{1}{4}\\)"]', 2, NULL, 3, 'mcq', 'ករណីស្រប \(\{HHT, HTH, THH\}\) មាន ៣ នាំឱ្យ \(P = \dfrac{3}{8} = 37.5\%\)។', 'ប្រូបាប', 'hard', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9030, 'គេបោះគ្រាប់ឡុកឡាក់ ២ គ្រាប់ព្រមគ្នា។ ប្រូបាបដែលផលបូកមុខលើនៃគ្រាប់ទាំងពីរស្មើ ៥ គឺ ៖', NULL, '["\\(\\dfrac{1}{9}\\)", "\\(\\dfrac{1}{12}\\)", "\\(\\dfrac{5}{36}\\)", "\\(\\dfrac{1}{6}\\)"]', 0, NULL, 3, 'mcq', 'គូដែលផលបូកស្មើ ៥ គឺ \(\{(1,4), (2,3), (3,2), (4,1)\}\) មាន ៤ នាំឱ្យ \(P = \dfrac{4}{36} = \dfrac{1}{9} \approx 11.11\%\)។', 'ប្រូបាប', 'hard', 1, '8', 'ប្រូបាប', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9031, 'គេបោះគ្រាប់ឡុកឡាក់ ២ គ្រាប់ព្រមគ្នា។ ប្រូបាបដែលផលបូកមុខលើនៃគ្រាប់ទាំងពីរធំជាង ឬស្មើ ៩ (\(\ge 9\)) គឺ ៖', NULL, '["\\(\\dfrac{5}{18}\\)", "\\(\\dfrac{1}{4}\\)", "\\(\\dfrac{7}{36}\\)", "\\(\\dfrac{1}{3}\\)"]', 0, NULL, 3, 'mcq', 'ផលបូក 9 (4 ករណី), 10 (3 ករណី), 11 (2 ករណី), 12 (1 ករណី) សរុប ១០ ករណី នាំឱ្យ \(P = \dfrac{10}{36} = \dfrac{5}{18} \approx 27.78\%\)។', 'ប្រូបាប', 'hard', 1, '8', 'ប្រូបាប', NULL, 0);
